using Asp.Versioning;using CashFlow.Launch.Api.Dtos.Requests;using CashFlow.Launch.Domain.Interfaces.Services;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;
namespace CashFlow.Launch.Api.Controllers;
[ApiController][ApiVersion("1.0")][Route("api/v{version:apiVersion}/credit-cards")][Authorize]public class CreditCardsController:ControllerBase{private readonly ICreditCardService _service;public CreditCardsController(ICreditCardService s)=>_service=s;[HttpPost]public async Task<IActionResult>Create(CreateCreditCardRequest r){var x=await _service.CreateCardAsync(r.Name,r.Limit,r.ClosingDay,r.DueDay);return x is null?BadRequest():Ok(x);}[HttpPut("{id:guid}")]public async Task<IActionResult>Update(Guid id,CreateCreditCardRequest r){var x=await _service.UpdateCardAsync(id,r.Name,r.Limit,r.ClosingDay,r.DueDay);return x is null?BadRequest():Ok(x);}[HttpDelete("{id:guid}")]public async Task<IActionResult>Delete(Guid id)=>await _service.DeleteCardAsync(id)?NoContent():NotFound();[HttpGet]public async Task<IActionResult>GetAll()=>Ok(await _service.GetCardsAsync());[HttpPost("purchases")]public async Task<IActionResult>CreatePurchase(CreateCreditCardPurchaseRequest r){var x=await _service.CreatePurchaseAsync(r.CreditCardId,r.CategoryId,r.Description,r.TotalAmount,r.InstallmentsCount,r.PurchaseDate);return x is null?BadRequest():Ok(x);}[HttpPut("purchases/{id:guid}")]public async Task<IActionResult>UpdatePurchase(Guid id,CreateCreditCardPurchaseRequest r){var x=await _service.UpdatePurchaseAsync(id,r.CreditCardId,r.CategoryId,r.Description,r.TotalAmount,r.InstallmentsCount,r.PurchaseDate);return x is null?BadRequest("Não foi possível editar. Compras com parcela já paga não podem ser alteradas."):Ok(x);}[HttpDelete("purchases/{id:guid}")]public async Task<IActionResult>DeletePurchase(Guid id)=>await _service.DeletePurchaseAsync(id)?NoContent():BadRequest("Não foi possível excluir. Compras com parcela já paga são preservadas.");[HttpGet("{creditCardId:guid}/invoices/{year:int}/{month:int}")]public async Task<IActionResult>GetInvoice(Guid creditCardId,int year,int month){var x=await _service.GetInvoiceAsync(creditCardId,year,month);return x is null?NotFound():Ok(x);}[HttpPost("installments/{installmentId:guid}/pay")]public async Task<IActionResult>Pay(Guid installmentId)=>await _service.MarkInstallmentPaidAsync(installmentId)?Ok():NotFound();}
